// The digest tick (spec 0004 T11, R9-R18). Hourly: SQL says who is due
// and unsent, this renders the template and sends it. Deliberately
// model-free -- a digest is a broadcast of figures the views already
// hold, and a generated one could disagree with an answer (R13).
//
// Idempotent by construction: the insert into digest_run is the send's
// gate, so a container that was down at 09:00 sends at 10:00 and one
// restarted twice in an hour sends once.
const crypto = require('crypto');
const http = require('http');
const https = require('https');
const fs = require('fs');
const { URL } = require('url');

const PG = 'http://postgrest:3000';

function b64url(buf) {
  return buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function mintAgentToken(memberId) {
  const header = b64url(Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'JWT' })));
  const payload = b64url(Buffer.from(JSON.stringify({ role: 'hh_agent', member_id: memberId, exp: Math.floor(Date.now() / 1000) + 120 })));
  const signingInput = `${header}.${payload}`;
  const signature = b64url(crypto.createHmac('sha256', $env.PGRST_JWT_SECRET).update(signingInput).digest());
  return `${signingInput}.${signature}`;
}

function httpJson(method, url, headers, body) {
  return new Promise((resolve, reject) => {
    const bodyStr = body !== undefined ? JSON.stringify(body) : undefined;
    const u = new URL(url);
    const options = {
      hostname: u.hostname, port: u.port, path: u.pathname + u.search, method,
      headers: Object.assign({ 'Content-Type': 'application/json' }, headers, bodyStr ? { 'Content-Length': Buffer.byteLength(bodyStr) } : {}),
    };
    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => {
        let parsed = null;
        try { parsed = data ? JSON.parse(data) : null; } catch (e) { parsed = data; }
        resolve({ status: res.statusCode, body: parsed });
      });
    });
    req.on('error', reject);
    if (bodyStr) req.write(bodyStr);
    req.end();
  });
}

function telegramSend(chatId, text) {
  return new Promise((resolve) => {
    const token = $env.TELEGRAM_DELIVERY_MODE === 'polling' ? $env.TELEGRAM_LOCAL_BOT_TOKEN : $env.TELEGRAM_BOT_TOKEN;
    if (!token) return resolve(false);
    const body = JSON.stringify({ chat_id: chatId, text });
    const req = https.request({
      hostname: 'api.telegram.org', path: `/bot${token}/sendMessage`, method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) },
    }, (res) => { res.on('data', () => {}); res.on('end', () => resolve(res.statusCode < 300)); });
    req.on('error', () => resolve(false));
    req.write(body);
    req.end();
  });
}

// ADR 0017: every string the system says without the agent comes out of
// the catalogue, and a missing key is a visible failure rather than a
// blank line in somebody's chat.
const catalogues = {};
function t(language, key, vars) {
  const lang = language === 'ru' ? 'ru' : 'en';
  if (!catalogues[lang]) catalogues[lang] = JSON.parse(fs.readFileSync(`/i18n/${lang}.json`, 'utf8'));
  let value = catalogues[lang][key];
  if (value === undefined) throw new Error(`i18n: missing key '${key}' in ${lang}`);
  for (const [name, val] of Object.entries(vars || {})) {
    value = value.split(`{{${name}}}`).join(String(val));
  }
  return value;
}

function money(minor, currency) {
  const symbol = { EUR: '€', USD: '$', RUB: '₽' }[currency || 'EUR'] || (currency || '');
  return `${(Number(minor || 0) / 100).toFixed(2)} ${symbol}`.trim();
}

async function main() {
  const item = ($input.first() && $input.first().json) || {};
  // Called through a webhook, so the payload is under `body`; called
  // directly in a test harness, it is the item itself.
  const input = item.body || item;
  // The clock is a parameter so a test can move it (plan.md); nothing
  // passes it in production, where SQL reads now() itself.
  const at = input.at ? `?at=${encodeURIComponent(input.at)}` : '';

  const readAuth = { Authorization: `Bearer ${mintAgentToken(null)}` };
  const [dueRes, settingRes] = await Promise.all([
    httpJson('GET', `${PG}/rpc/digest_due${at}`, readAuth),
    httpJson('GET', `${PG}/household_setting?key=eq.default_currency&select=value`, readAuth),
  ]);
  // The household's currency is a row, never a constant here (ADR 0034);
  // the spend views carry minor units and say nothing about currency.
  const householdCurrency = ((settingRes.body || [])[0] || {}).value || 'EUR';
  if (dueRes.status < 200 || dueRes.status >= 300) {
    return [{ json: { error: (dueRes.body && dueRes.body.message) || `could not ask who is due: ${dueRes.status}`, sent: [] } }];
  }

  const sent = [];
  for (const due of dueRes.body || []) {
    const auth = { Authorization: `Bearer ${mintAgentToken(due.member_id)}` };

    // The gate: whoever writes this row owns the send. A duplicate is
    // not an error here, it is the answer to "has this gone already?".
    const claim = await httpJson('POST', `${PG}/digest_run`, Object.assign({ Prefer: 'return=minimal' }, auth), {
      member_id: due.member_id, kind: due.kind, period_start: due.period_start,
    });
    if (claim.status === 409) continue;
    if (claim.status < 200 || claim.status >= 300) {
      sent.push({ member_id: due.member_id, kind: due.kind, error: (claim.body && claim.body.message) || claim.status });
      continue;
    }

    const [totalRes, categoryRes, reconRes, channelRes] = await Promise.all([
      httpJson('GET', `${PG}/v_period_spend?period=eq.${due.period}`, auth),
      httpJson('GET', `${PG}/v_category_spend?period=eq.${due.period}&amount_minor=gt.0&order=amount_minor.desc&limit=3`, auth),
      httpJson('GET', `${PG}/v_period_reconciliation?period=eq.${due.period}`, auth),
      httpJson('GET', `${PG}/member_channel?member_id=eq.${due.member_id}&kind=eq.telegram&select=external_id`, auth),
    ]);

    const total = (totalRes.body || [])[0] || null;
    const categories = categoryRes.body || [];
    const recon = (reconRes.body || [])[0] || null;
    const currency = householdCurrency;

    // R16: a period with nothing in it is said in one line, never
    // suppressed -- silence would read as a broken digest.
    let text;
    if (!total || !Number(total.amount_minor)) {
      text = t(due.language, 'digest_empty', {
        period_start: (total && total.period_start) || due.period_start,
        period_end: (total && total.period_end) || due.period_start,
      });
    } else {
      text = t(due.language, due.kind === 'weekly' ? 'digest_weekly' : 'digest_monthly', {
        period_start: total.period_start,
        period_end: total.period_end,
        total: money(total.amount_minor, currency),
        previous: money(total.previous_amount_minor, currency),
        unconfirmed: money(total.unconfirmed_amount_minor, currency),
        categories: categories.map((c) => `${c.category_slug} ${money(c.amount_minor, currency)}`).join(', '),
        // R17: the period's reconciliation status is stated rather
        // than waited for.
        reconciliation: recon && recon.reconciled ? '' : t(due.language, 'digest_unreconciled', {}),
      }).trim();
    }

    const chat = (channelRes.body || [])[0];
    const delivered = chat ? await telegramSend(chat.external_id, text) : false;
    sent.push({ member_id: due.member_id, kind: due.kind, period: due.period, period_start: due.period_start, language: due.language, text, delivered });
  }

  return [{ json: { sent, count: sent.length } }];
}

return main();
